select count(1) from PRD_PLAN_INFO
(to_char(VDATE,'yyyy-MM-dd') = #{planningStartDate} AND to_char(EDATE,'yyyy-MM-dd') = #{planningEndDate})
AND PRD_PLAN_CODE <> #{planningNo}

select count(1) from PRD_PLAN_INFO
( (to_char(VDATE,'yyyy-MM-dd') > #{planningStartDate} AND to_char(VDATE,'yyyy-MM-dd') < #{planningEndDate}) or (to_char(EDATE,'yyyy-MM-dd') > #{planningStartDate} AND to_char(EDATE,'yyyy-MM-dd') < #{planningEndDate}) or (TO_CHAR(VDATE,'yyyy-MM-dd') < #{planningStartDate} AND TO_CHAR(EDATE, 'yyyy-MM-dd') > #{planningEndDate}) )
AND PRD_PLAN_CODE <> #{planningNo}

